package challenge

// Core returns the offline tutorial. These authored challenges deliberately
// cover recall of one concept at a time before combining concepts.
func Core() []Challenge {
	items := []Challenge{
		{ID: "literal-001", Act: 1, Title: "First Signal", Prompt: "Print lines containing ERROR from vault.log.", Tags: []string{"literal"}, Difficulty: 1, Fixtures: map[string]string{"vault.log": "INFO opened\nERROR seal broken\nWARN dust\nERROR intruder\n"}, WantOutput: "ERROR seal broken\nERROR intruder\n", WantExit: 0, Hints: []string{"grep takes a pattern and a file.", "Use: grep PATTERN FILE"}, Explanation: "grep prints every input line containing the pattern."},
		{ID: "case-001", Act: 1, Title: "Whispered Signals", Prompt: "Print every case variation of warning from alarms.log.", Tags: []string{"case", "-i"}, Difficulty: 1, Fixtures: map[string]string{"alarms.log": "warning low\nWARNING high\nWarning medium\nsafe\n"}, WantOutput: "warning low\nWARNING high\nWarning medium\n", WantExit: 0, Hints: []string{"Case should not matter.", "Use grep -i."}, Explanation: "-i performs case-insensitive matching."},
		{ID: "fixed-001", Act: 1, Title: "Literal Rune", Prompt: "Find the literal text a.b in runes.txt (the dot is not a wildcard).", Tags: []string{"fixed", "-F"}, Difficulty: 1, Fixtures: map[string]string{"runes.txt": "a.b\nacb\na-b\n"}, WantOutput: "a.b\n", WantExit: 0, Hints: []string{"Treat the pattern as a fixed string.", "Use grep -F."}, Explanation: "-F interprets the pattern literally rather than as a regular expression."},
		{ID: "word-001", Act: 1, Title: "Whole Sigil", Prompt: "Print lines containing the whole word cat from beasts.txt.", Tags: []string{"word", "-w"}, Difficulty: 1, Fixtures: map[string]string{"beasts.txt": "cat\nscatter\ncat nap\nbobcat\n"}, WantOutput: "cat\ncat nap\n", WantExit: 0, Hints: []string{"Partial words must not match.", "Use grep -w."}, Explanation: "-w requires word boundaries around the match."},
		{ID: "line-001", Act: 1, Title: "Exact Inscription", Prompt: "Print only the line whose complete contents are READY from state.txt.", Tags: []string{"line", "-x"}, Difficulty: 1, Fixtures: map[string]string{"state.txt": "READY\nNOT READY\nREADY NOW\n"}, WantOutput: "READY\n", WantExit: 0, Hints: []string{"The entire line must match.", "Use grep -x."}, Explanation: "-x accepts only matches spanning the complete line."},
		{ID: "exit-001", Act: 1, Title: "Silent Gate", Prompt: "Search for dragon in empty.txt. No output and exit code 1 is the correct result.", Tags: []string{"exit-code"}, Difficulty: 2, Fixtures: map[string]string{"empty.txt": "kobold\nslime\n"}, WantOutput: "", WantExit: 1, Hints: []string{"A missing match is not a grep error.", "Run grep dragon empty.txt."}, Explanation: "grep returns 1 when no lines match; operational errors return 2."},
		{ID: "anchor-start-001", Act: 2, Title: "Vanguard Anchor", Prompt: "Print lines that begin with TODO from tasks.txt.", Tags: []string{"bre", "anchor"}, Difficulty: 2, Fixtures: map[string]string{"tasks.txt": "TODO forge key\nlate TODO\nTODO map vault\n"}, WantOutput: "TODO forge key\nTODO map vault\n", WantExit: 0, Hints: []string{"Anchor the pattern at the beginning.", "Use ^ at the pattern start."}, Explanation: "^ anchors a regular expression to the start of a line."},
		{ID: "anchor-end-001", Act: 2, Title: "Rear Guard", Prompt: "Print lines ending in .conf from files.txt.", Tags: []string{"bre", "anchor", "escaping"}, Difficulty: 2, Fixtures: map[string]string{"files.txt": "app.conf\nconf.old\nweirdXconf\ndb.conf\n"}, WantOutput: "app.conf\ndb.conf\n", WantExit: 0, Hints: []string{"Anchor the end and make the dot literal.", "Use a quoted pattern like '\\.conf$'."}, Explanation: "$ anchors the end; escaping the dot prevents wildcard matching."},
		{ID: "class-001", Act: 2, Title: "Numbered Seals", Prompt: "Print seal lines ending in one digit from seals.txt.", Tags: []string{"bre", "class"}, Difficulty: 2, Fixtures: map[string]string{"seals.txt": "seal-1\nseal-x\nseal-22\nseal-7\n"}, WantOutput: "seal-1\nseal-7\n", WantExit: 0, Hints: []string{"Use a digit character class and an end anchor.", "Try 'seal-[[:digit:]]$'."}, Explanation: "POSIX character classes are portable and $ prevents extra trailing digits."},
		{ID: "ere-001", Act: 2, Title: "Forked Passage", Prompt: "Print lines containing either sword or shield from loot.txt.", Tags: []string{"ere", "-E", "alternation"}, Difficulty: 2, Fixtures: map[string]string{"loot.txt": "iron sword\nwood staff\nbronze shield\nboots\n"}, WantOutput: "iron sword\nbronze shield\n", WantExit: 0, Hints: []string{"Alternation is clearest in ERE mode.", "Use grep -E 'sword|shield'."}, Explanation: "-E enables extended regular expressions where | expresses alternatives."},
		{ID: "literal-002", Act: 1, Title: "Twin Archives", Prompt: "Find key in both east.txt and west.txt, preserving grep's filename prefixes.", Tags: []string{"literal", "files"}, Difficulty: 1, Fixtures: map[string]string{"east.txt": "key amber\ndust\n", "west.txt": "moss\nkey iron\n"}, WantOutput: "east.txt:key amber\nwest.txt:key iron\n", WantExit: 0, Hints: []string{"Pass both filenames to grep.", "Use grep key east.txt west.txt."}, Explanation: "With multiple files, grep prefixes matching lines with their filename."},
		{ID: "case-word-001", Act: 1, Title: "Named Beast", Prompt: "Find the whole word ORC regardless of case in scouts.txt.", Tags: []string{"case", "word"}, Difficulty: 2, Fixtures: map[string]string{"scouts.txt": "orc camp\nORCHID\none ORC\nOrcish\n"}, WantOutput: "orc camp\none ORC\n", WantExit: 0, Hints: []string{"Combine case-insensitive and whole-word modes.", "Use grep -iw ORC scouts.txt."}, Explanation: "Options can be combined: -i ignores case and -w rejects partial words.", RequiredArgs: []string{"-i", "-w"}},
		{ID: "fixed-002", Act: 1, Title: "Bracket Trap", Prompt: "Find the literal string [vault] in marks.txt.", Tags: []string{"fixed", "quoting"}, Difficulty: 1, Fixtures: map[string]string{"marks.txt": "[vault]\nv\na\n"}, WantOutput: "[vault]\n", WantExit: 0, Hints: []string{"Brackets are regex syntax unless fixed mode is used.", "Use grep -F '[vault]' marks.txt."}, Explanation: "-F avoids interpreting bracket expressions.", RequiredArgs: []string{"-F"}},
		{ID: "line-case-001", Act: 1, Title: "Sealed State", Prompt: "Print complete lines equal to sealed, in any case, from doors.txt.", Tags: []string{"line", "case"}, Difficulty: 2, Fixtures: map[string]string{"doors.txt": "SEALED\nsealed shut\nSealed\nunsealed\n"}, WantOutput: "SEALED\nSealed\n", WantExit: 0, Hints: []string{"Combine whole-line and case-insensitive matching.", "Use grep -ix sealed doors.txt."}, Explanation: "-x constrains the complete line while -i folds case.", RequiredArgs: []string{"-i", "-x"}},
		{ID: "exit-error-001", Act: 1, Title: "Broken Passage", Prompt: "Search missing.txt and observe grep's operational-error exit code. The error text is ignored; no stdout is expected.", Tags: []string{"exit-code", "error"}, Difficulty: 2, Fixtures: map[string]string{"present.txt": "nothing\n"}, WantOutput: "", WantExit: 2, Hints: []string{"The requested file intentionally does not exist.", "Run grep rune missing.txt."}, Explanation: "GNU grep uses exit code 2 for an operational error."},
		{ID: "bre-repeat-001", Act: 2, Title: "Paired Digits", Prompt: "Using BRE, print lines made of exactly two digits from codes.txt.", Tags: []string{"bre", "quantifier"}, Difficulty: 3, Fixtures: map[string]string{"codes.txt": "7\n42\n123\nab\n09\n"}, WantOutput: "42\n09\n", WantExit: 0, Hints: []string{"BRE interval braces must be escaped.", "Use '^[[:digit:]]\\{2\\}$'."}, Explanation: "In BRE, escaped braces form an interval quantifier."},
		{ID: "ere-plus-001", Act: 2, Title: "Echoing Horn", Prompt: "Print lines consisting of ha followed by one or more exclamation marks.", Tags: []string{"ere", "quantifier"}, Difficulty: 2, Fixtures: map[string]string{"horn.txt": "ha\nha!\nha!!!\naha!\n"}, WantOutput: "ha!\nha!!!\n", WantExit: 0, Hints: []string{"Use ERE for the + quantifier.", "Use grep -E '^ha!+$' horn.txt."}, Explanation: "In ERE, + means one or more of the preceding expression.", RequiredArgs: []string{"-E"}},
		{ID: "ere-group-001", Act: 2, Title: "Colored Keys", Prompt: "Print exactly red-key or blue-key from keys.txt.", Tags: []string{"ere", "group", "alternation"}, Difficulty: 3, Fixtures: map[string]string{"keys.txt": "red-key\nblue-key\ngreen-key\nred-door\n"}, WantOutput: "red-key\nblue-key\n", WantExit: 0, Hints: []string{"Group the color alternatives.", "Use grep -E '^(red|blue)-key$'."}, Explanation: "ERE groups alternatives with parentheses.", RequiredArgs: []string{"-E"}},
		{ID: "ere-optional-001", Act: 2, Title: "Armored Spelling", Prompt: "Print both armor and armour from scroll.txt.", Tags: []string{"ere", "quantifier"}, Difficulty: 2, Fixtures: map[string]string{"scroll.txt": "armor\narmour\narmorer\n"}, WantOutput: "armor\narmour\n", WantExit: 0, Hints: []string{"The u is optional.", "Use grep -E '^armou?r$'."}, Explanation: "ERE ? makes the preceding atom optional.", RequiredArgs: []string{"-E"}},
		{ID: "quote-space-001", Act: 2, Title: "Two-Word Charm", Prompt: "Print lines containing the phrase silver key from notes.txt.", Tags: []string{"quoting", "literal"}, Difficulty: 1, Fixtures: map[string]string{"notes.txt": "silver key found\nsilver\nkey silver\n"}, WantOutput: "silver key found\n", WantExit: 0, Hints: []string{"The shell-like parser must receive the phrase as one argument.", "Quote 'silver key'."}, Explanation: "Quoting preserves spaces inside a single pattern argument."},
		{ID: "ere-class-001", Act: 2, Title: "Hex Ward", Prompt: "Print lines containing only uppercase hexadecimal characters from hex.txt.", Tags: []string{"ere", "class", "anchor"}, Difficulty: 3, Fixtures: map[string]string{"hex.txt": "A0FF\nbeef\nG123\n99\n"}, WantOutput: "A0FF\n99\n", WantExit: 0, Hints: []string{"Use an uppercase range plus digits.", "Use grep -E '^[A-F0-9]+$'."}, Explanation: "Anchors and + constrain the entire line to the chosen class.", RequiredArgs: []string{"-E"}},
		{ID: "multiple-pattern-001", Act: 2, Title: "Double Bounty", Prompt: "Print lines containing goblin or troll using two -e patterns.", Tags: []string{"multiple-pattern", "-e"}, Difficulty: 2, Fixtures: map[string]string{"bounties.txt": "goblin scout\nslime\ntroll guard\n"}, WantOutput: "goblin scout\ntroll guard\n", WantExit: 0, Hints: []string{"grep accepts more than one -e expression.", "Use grep -e goblin -e troll bounties.txt."}, Explanation: "Each -e supplies another pattern; a line matching any is selected.", RequiredArgs: []string{"-e"}},
		{ID: "bre-group-001", Act: 2, Title: "Old Binding", Prompt: "Using BRE grouping, print exactly abab or ababab from chants.txt.", Tags: []string{"bre", "group", "quantifier"}, Difficulty: 4, Fixtures: map[string]string{"chants.txt": "ab\nabab\nababab\nabababab\n"}, WantOutput: "abab\nababab\n", WantExit: 0, Hints: []string{"BRE groups and intervals are escaped.", "Use '^\\(ab\\)\\{2,3\\}$'."}, Explanation: "BRE uses escaped parentheses and braces for groups and intervals."},
		{ID: "ere-bounded-001", Act: 2, Title: "Measured Knock", Prompt: "Print knock followed by two through four o characters from knocks.txt.", Tags: []string{"ere", "quantifier"}, Difficulty: 3, Fixtures: map[string]string{"knocks.txt": "knocko\nknockoo\nknockooo\nknockoooo\nknockooooo\n"}, WantOutput: "knockoo\nknockooo\nknockoooo\n", WantExit: 0, Hints: []string{"ERE interval braces do not need backslashes.", "Use grep -E '^knocko{2,4}$'."}, Explanation: "ERE {m,n} bounds repetition inclusively.", RequiredArgs: []string{"-E"}},
		{ID: "escape-plus-001", Act: 2, Title: "Literal Spark", Prompt: "Using BRE, find the literal text +1 in charges.txt.", Tags: []string{"bre", "escaping"}, Difficulty: 2, Fixtures: map[string]string{"charges.txt": "+1 charge\n11 charge\nplus one\n"}, WantOutput: "+1 charge\n", WantExit: 0, Hints: []string{"In GNU BRE, an unescaped plus is literal.", "Use grep '+1' charges.txt."}, Explanation: "BRE and ERE assign different meanings to some metacharacters."},
		{ID: "ere-combined-001", Act: 2, Title: "Foundry Trial", Prompt: "Print IDs shaped like Q- followed by exactly three digits from ids.txt.", Tags: []string{"ere", "class", "quantifier", "anchor"}, Difficulty: 4, Fixtures: map[string]string{"ids.txt": "Q-007\nQ-42\nX-123\nQ-999\nQ-1234\n"}, WantOutput: "Q-007\nQ-999\n", WantExit: 0, Hints: []string{"Combine anchors, a digit class, and a count.", "Use grep -E '^Q-[[:digit:]]{3}$'."}, Explanation: "Anchors, classes, and bounded repetition compose into precise validation patterns.", RequiredArgs: []string{"-E"}},
	}
	hidden := map[string]TestCase{
		"literal-001":      {Fixtures: map[string]string{"vault.log": "ERROR first\nINFO calm\nERROR last\n"}, WantOutput: "ERROR first\nERROR last\n", WantExit: 0},
		"case-001":         {Fixtures: map[string]string{"alarms.log": "WaRnInG mixed\nclear\nwarning low\n"}, WantOutput: "WaRnInG mixed\nwarning low\n", WantExit: 0},
		"fixed-001":        {Fixtures: map[string]string{"runes.txt": "axb\na.b\naab\n"}, WantOutput: "a.b\n", WantExit: 0},
		"word-001":         {Fixtures: map[string]string{"beasts.txt": "catfish\na cat sleeps\ncat\n"}, WantOutput: "a cat sleeps\ncat\n", WantExit: 0},
		"line-001":         {Fixtures: map[string]string{"state.txt": "READY!\nREADY\n READY\n"}, WantOutput: "READY\n", WantExit: 0},
		"exit-001":         {Fixtures: map[string]string{"empty.txt": "wyvern\nrat\n"}, WantOutput: "", WantExit: 1},
		"anchor-start-001": {Fixtures: map[string]string{"tasks.txt": "TODO one\n TODO two\ndone TODO\n"}, WantOutput: "TODO one\n", WantExit: 0},
		"anchor-end-001":   {Fixtures: map[string]string{"files.txt": "x.conf\nx.conf.bak\nyXconf\n"}, WantOutput: "x.conf\n", WantExit: 0},
		"class-001":        {Fixtures: map[string]string{"seals.txt": "seal-0\nseal-10\nseal-a\nseal-9\n"}, WantOutput: "seal-0\nseal-9\n", WantExit: 0},
		"ere-001":          {Fixtures: map[string]string{"loot.txt": "shield wall\nwand\nsword edge\n"}, WantOutput: "shield wall\nsword edge\n", WantExit: 0},
	}
	for i := range items {
		if test, ok := hidden[items[i].ID]; ok {
			items[i].HiddenTests = []TestCase{test}
		}
	}
	return items
}
